def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')

    if n >= 5 and opp_def >= n * 0.7:
        return 'D'

    retaliated = (history[3][1] == 'D')

    if retaliated:
        if n >= 99:
            return 'D'
        if n == 4:
            return 'C'
        if last_opp == 'D':
            if last_me == 'D':
                return 'C'
            else:
                if n >= 3 and opp[-3:].count('D') >= 2:
                    return 'D'
                return 'C'
        else:
            return 'C'
    else:
        if n >= 89:
            return 'D'
        if last_opp == 'D':
            if opp_def <= 1 and n > 10:
                return 'C'
            return 'D'
        else:
            if my_def * 5 < n:
                return 'D'
            return 'C'
